(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory();else root.RepoStore=factory()})(globalThis,function(){
'use strict';
const channels=['All technologies','React','Next.js','Three.js','Node.js','Vue','Svelte','Angular','Python','Flutter','Rust','Go'];
const rules={'React':['react','reactjs','react-native'],'Next.js':['next','nextjs','next-js'],'Three.js':['three','threejs','three-js','three.js','react-three-fiber'],'Node.js':['node','nodejs','node-js','express','fastify','nestjs'],'Vue':['vue','vuejs','vue3','nuxt'],'Svelte':['svelte','sveltekit'],'Angular':['angular'],'Python':['python','django','flask','fastapi'],'Flutter':['flutter'],'Rust':['rust'],'Go':['golang']};
function technologies(r,pkg={}){const found=new Set(r.technologies||[]),topics=(r.topics||[]).map(s=>s.toLowerCase());const deps={...pkg.dependencies,...pkg.devDependencies};for(const [name,keys]of Object.entries(rules))if(topics.some(t=>keys.includes(t)))found.add(name);const packages={'react':'React','next':'Next.js','three':'Three.js','@react-three/fiber':'Three.js','express':'Node.js','fastify':'Node.js','@nestjs/core':'Node.js','vue':'Vue','nuxt':'Vue','svelte':'Svelte','@angular/core':'Angular'};for(const [key,name]of Object.entries(packages))if(deps[key])found.add(name);const language={Python:'Python',Rust:'Rust',Go:'Go'}[r.language];if(language)found.add(language);return channels.filter(c=>found.has(c))}
function popularity(r){return .7*Math.log1p(Math.max(0,r.stars||0))+.3*Math.log1p(Math.max(0,r.forks||0))}
function recordMetrics(r,now=Date.now()){if(typeof r.stars!=='number'||typeof r.forks!=='number')return r;const date=new Date(now).toISOString();const day=date.slice(0,10);const metrics=(r.metrics||[]).filter(p=>Date.parse(p.at)>=now-35*86400000&&p.at.slice(0,10)!==day);metrics.push({at:date,stars:r.stars,forks:r.forks});return {...r,metrics:metrics.sort((a,b)=>Date.parse(a.at)-Date.parse(b.at))}}
function trend(r,now=Date.now()){if(Object.hasOwn(r,"trendSummary")){const at=Date.parse(r.lastCheckedAt||r.trendComputedAt);return Number.isFinite(at)&&now-at<=2*86400000?r.trendSummary:null;}const measured=Date.parse(r.lastCheckedAt);if(Number.isFinite(measured)){if(now-measured>2*86400000)return null;now=Math.min(now,measured)}const samples=(r.metrics||[]).filter(p=>Date.parse(p.at)<=now-86400000&&Date.parse(p.at)>=now-9*86400000).sort((a,b)=>Date.parse(a.at)-Date.parse(b.at));if(!samples.length)return null;const target=now-7*86400000;const baseline=samples.reduce((best,p)=>Math.abs(Date.parse(p.at)-target)<Math.abs(Date.parse(best.at)-target)?p:best);const days=(now-Date.parse(baseline.at))/86400000,stars=Math.max(0,(r.stars||0)-baseline.stars),forks=Math.max(0,(r.forks||0)-baseline.forks);return {stars,forks,days,score:.7*Math.log1p(stars/days)+.3*Math.log1p(forks/days)}}
function recentRelease(r,now=Date.now()){const date=Date.parse(r.latestRelease?.publishedAt);return Number.isFinite(date)&&date<=now&&now-date<=30*86400000}
function sorted(repos,sort='popular',now=Date.now()){const list=[...repos];const score=(r)=>sort==='trending'?(trend(r,now)?.score??-1):popularity(r);if(sort==='trending')return list.filter(r=>(trend(r,now)?.score||0)>0).sort((a,b)=>score(b)-score(a));return list.sort((a,b)=>score(b)-score(a))}
function previewUrl(value){if(typeof value!=='string')return null;if(/^previews\/[a-f0-9]{24}\.jpg$/.test(value))return value;try{const u=new URL(value);return u.protocol==='https:'?u.href:null}catch{return null}}
function images(r){const out=[];for(const item of r.screenshots||[]){if(item.kind==='demo'&&item.url&&item.url!==r.demo)continue;const src=previewUrl(item.src);if(src&&!out.some(i=>i.src===src))out.push({...item,src})}return out.slice(0,6)}
function readmeImages(markdown,repo){const images=[];for(const m of String(markdown||'').matchAll(/!\[([^\]]*)\]\(([^\s)]+)(?:\s+[^)]*)?\)/g)){if(!/screenshot|preview|screen shot|application|app interface/i.test(m[1]))continue;let src=m[2];try{if(!/^https?:/.test(src))src=new URL(src,`https://raw.githubusercontent.com/${repo.full}/${encodeURIComponent(repo.branch||'main')}/`).href;src=previewUrl(src);if(src)images.push({src,kind:'readme',alt:m[1]})}catch{}}return images.slice(0,4)}
return {channels,technologies,popularity,recordMetrics,trend,recentRelease,sorted,previewUrl,images,readmeImages};
});
